<template><view class="login-page"><view class="topbar"><view class="back" role="button" aria-label="返回" @tap="back"><AppIcon name="chevron-left" :size="20"/></view></view><view class="login-content"><view class="brand-mark"><AppIcon name="brand-assistant" :size="46"/></view><text class="title">账号登录</text><text class="subtitle">登录你的统子哥账号</text><view class="login-form"><view class="field"><text>账号</text><view class="input-wrap"><AppIcon name="user" :size="19" color="#8d97a8"/><input v-model="username" placeholder="请输入账号" autocomplete="username" :disabled="busy"/></view></view><view class="field"><text>密码</text><view class="input-wrap"><AppIcon name="shield" :size="19" color="#8d97a8"/><input v-model="password" :password="!showPassword" placeholder="请输入密码" :disabled="busy" confirm-type="go" @confirm="submit"/><text class="visibility" role="button" @tap="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</text></view></view><view class="remember" role="checkbox" :aria-checked="remember" @tap="remember=!remember"><view class="check" :class="{checked:remember}"><text v-if="remember">✓</text></view><text>记住账号</text></view><text v-if="error" class="error" role="alert">{{error}}</text><button class="primary" :disabled="busy" @tap="submit">{{busy?'正在登录…':'登录'}}</button></view></view><LoginCaptcha :visible="captchaVisible" @close="captchaVisible=false;busy=false" @success="verified"/></view></template>
<script setup lang="ts">
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import AppIcon from '@/components/AppIcon.vue';import LoginCaptcha from '@/components/LoginCaptcha.vue';import {accountLogin,prepareAccountLogin} from '@/services/auth/account';import {loginDestination} from '@/modules/auth-navigation';
const remembered=uni.getStorageSync('assistant.login-account')||{},username=ref(remembered.username||''),password=ref(''),remember=ref(!!remembered.username),showPassword=ref(false),busy=ref(false),error=ref(''),captchaVisible=ref(false);let destination='/pages/mine/index';
onLoad(q=>{try{destination=loginDestination(q?.redirect);}catch{destination=loginDestination();}});
function back(){if(getCurrentPages().length>1)uni.navigateBack();else uni.reLaunch({url:'/pages/mine/index'});}
async function submit(){if(busy.value)return;error.value='';if(!username.value.trim()||!password.value){error.value='请输入账号和密码';return;}busy.value=true;try{await prepareAccountLogin();if((import.meta.env.VITE_APP_CAPTCHA_ENABLE??String(import.meta.env.PROD))==='true'){captchaVisible.value=true;return;}await login();}catch(e){error.value=e instanceof Error?e.message:'登录失败，请重试';busy.value=false;}}
async function verified(value:string){captchaVisible.value=false;await login(value);}
async function login(verification?:string){try{await accountLogin.authenticate({username:username.value.trim(),password:password.value,captchaVerification:verification});password.value='';if(remember.value)uni.setStorageSync('assistant.login-account',{username:username.value.trim()});else uni.removeStorageSync('assistant.login-account');uni.reLaunch({url:destination});}catch{error.value='登录失败，请核对账号、密码或验证信息';}finally{busy.value=false;}}
</script>
<style scoped>
.login-page{box-sizing:border-box;min-height:100vh;background:radial-gradient(ellipse at 100% 0,#e7edff,transparent 48%),#fbfcff;padding:calc(16px + env(safe-area-inset-top)) 28px 40px;color:#202735}.topbar{max-width:400px;margin:auto}.back{display:inline-flex;padding:10px;margin-left:-10px}.login-content{max-width:360px;margin:56px auto 0}.brand-mark{display:flex;align-items:center;justify-content:center;width:76px;height:76px;background:#fff;border:1px solid #edf0fa;box-shadow:0 14px 40px #354dc510;border-radius:26px;margin-bottom:30px}.title{display:block;font-size:32px;font-weight:650;letter-spacing:1px}.subtitle{display:block;font-size:14px;color:#9098a9;margin:12px 0 44px}.field{margin-bottom:24px}.field>text{display:block;font-size:13px;margin-bottom:12px;color:#616b7f}.input-wrap{display:flex;align-items:center;gap:12px;background:#f0f3f9;border:1px solid transparent;border-radius:16px;padding:0 16px;height:58px}.input-wrap:focus-within{border-color:#6b85e9;background:#fff}input{flex:1;min-width:0;font-size:16px;height:54px}.visibility{color:#73809b;font-size:12px;padding:12px 0 12px 10px}.remember{display:flex;align-items:center;gap:9px;color:#8992a4;font-size:13px;margin:0 0 34px}.check{height:17px;width:17px;border:1px solid #ccd4e1;border-radius:6px;display:flex;align-items:center;justify-content:center;color:white}.checked{background:#4966dd;border-color:#4966dd}.primary{height:56px;line-height:56px;background:#4966dd;color:#fff;border-radius:18px;font-size:16px;font-weight:600;box-shadow:0 10px 24px #4966dd24}.primary::after{border:0}.primary[disabled]{opacity:.55}.error{display:block;color:#bd4545;font-size:13px;margin:0 0 16px}@media(max-height:700px){.login-content{margin-top:20px}.subtitle{margin-bottom:28px}.brand-mark{margin-bottom:22px}}
</style>
<style scoped>
.login-page{background:#fff;padding-left:30px;padding-right:30px}.login-content{margin-top:42px}.brand-mark{width:60px;height:60px;background:transparent;border:0;box-shadow:none;border-radius:18px;margin-bottom:26px}.title{font-size:28px;letter-spacing:0}.subtitle{margin:10px 0 36px;font-size:13px}.input-wrap{background:#f5f6f8;border-radius:12px;height:54px}.field{margin-bottom:20px}.primary{height:52px;line-height:52px;border-radius:13px;box-shadow:none;background:#4964d8}.remember{margin-bottom:28px}@media(max-height:700px){.login-content{margin-top:16px}}
</style>
